const cfg = $('Load Env (no secrets in graph)').first().json;
const tavily = $('Tavily Discovery').first().json;
const truthRaw = $input.first().json;

function arr(x) {
  if (Array.isArray(x)) return x;
  if (x && Array.isArray(x.data)) return x.data;
  if (x && x.data && Array.isArray(x.data.deliverables)) return x.data.deliverables;
  if (x && Array.isArray(x.deliverables)) return x.deliverables;
  return [];
}

const fallbackPkgs = [
  {id:'setup-quick',name:'Quick setup',description:'Portal, login, payments, contact.',billing:'one_time',anchorEur:549},
  {id:'integration',name:'Custom integration',description:'API, AI, email, payments connected to your tools.',billing:'one_time',anchorEur:1190},
  {id:'workflow-design',name:'Workflow design',description:'Process mapping into automations and SOP documentation.',billing:'one_time',anchorEur:690},
  {id:'audit',name:'Technical audit',description:'Security review, stack assessment, migration plan.',billing:'one_time',anchorEur:590},
  {id:'lead-gen-retainer',name:'Lead gen retainer',description:'Leads, outreach, and CRM pipeline every month.',billing:'monthly',anchorEur:499},
  {id:'custom-software',name:'Software starter kit',description:'Starter Node API + SPA scaffold — not unlimited custom build.',billing:'one_time',anchorEur:4900}
];

let packages = arr(truthRaw).map(p => ({
  id: String(p.id || p.deliverableId || ''),
  name: String(p.name || ''),
  description: String(p.description || ''),
  billing: String(p.billing || 'one_time'),
  anchorEur: Number(p.anchorEur || p.priceEur || 0) || null,
  includes: Array.isArray(p.includes) ? p.includes : [],
  excludes: Array.isArray(p.excludes) ? p.excludes : []
})).filter(p => p.id);

if (!packages.length) packages = fallbackPkgs;

const results = Array.isArray(tavily.results) ? tavily.results : [];
const emailRe = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const phoneRe = /\+?\d[\d\s().-]{7,}\d/g;

function redact(s) {
  return String(s || '').replace(emailRe, '[REDACTED_EMAIL]').replace(phoneRe, '[REDACTED_PHONE]').slice(0, 2500);
}

function host(u) {
  try { return new URL(u).hostname; } catch { return ''; }
}

const leads = results.map((r, i) => ({
  id: `tv-${Date.now()}-${i}`,
  source: (String(r.url||'').includes('reddit') ? 'reddit' : (String(r.url||'').includes('ycombinator') ? 'hackernews' : 'web')),
  title: redact(r.title || 'untitled').slice(0, 500),
  bodyExcerpt: redact(r.content || r.snippet || ''),
  urlHost: host(r.url),
  url: r.url || null,
  discoveredAt: new Date().toISOString()
})).filter(l => l.bodyExcerpt.length > 40);

if (!leads.length) {
  return [{ json: { skip: true, reason: 'no_leads', runId: cfg.runId } }];
}

const truth = {
  fetchedAt: new Date().toISOString(),
  brandName: 'Omni Group Tech',
  publicSiteUrl: cfg.siteUrl,
  checkoutBaseUrl: cfg.checkoutBase,
  packages,
  modules: [
    {id:'atina',name:'Atina',tagline:'API & SaaS core',description:'Auth, billing, catalog'},
    {id:'astra',name:'Astra',tagline:'Automation & workflows',description:'Pipelines and observability'},
    {id:'titan',name:'Titan',tagline:'Operations & integrations',description:'Ops and integrations'}
  ],
  terms: {
    disclaimerFooter: '— Omni Group Tech · Packages & pricing: https://omnigrouptech.com/pricing · Terms: https://omnigrouptech.com/legal/terms · This is not a binding offer; checkout confirms scope.',
    forbiddenClaims: ['100% money-back','guaranteed ROI','unlimited custom']
  }
};

return leads.map(lead => ({
  json: {
    ...cfg,
    lead,
    truth,
    skip: false
  }
}));

const item = $input.first().json;
const min = Number(item.delayMin || 240);
const max = Number(item.delayMax || 1080);
const delaySec = Math.floor(min + Math.random() * (Math.max(max, min) - min + 1));
return [{ json: { ...item, humanDelaySec: delaySec, humanDelayMinutes: Math.round(delaySec / 60) } }];

