const prev = $('Compute Human Delay').item.json;
const resp = $input.first().json;
let agent1 = null;
let parseError = null;
try {
  const content = resp.choices?.[0]?.message?.content || resp.message?.content || '';
  agent1 = JSON.parse(content);
} catch (e) {
  parseError = String(e.message || e);
}
const score = Number(agent1?.relevanceScore || 0);
const discard = Boolean(agent1?.discard) || score < 7 || !agent1;
const pkgId = agent1?.checkoutPackageId || agent1?.recommendedPackageId || null;
const checkoutUrl = pkgId ? `${String(prev.checkoutBase).replace(/\/$/,'')}?package=${encodeURIComponent(pkgId)}` : null;
return [{
  json: {
    ...prev,
    agent1,
    agent1ParseError: parseError,
    passScout: !discard && !parseError,
    platformCheckoutUrl: checkoutUrl
  }
}];

