const prev = $('Parse Agent 1 + Score Gate').item.json;
const resp = $input.first().json;
let agent2 = null;
let parseError = null;
try {
  const content = resp.choices?.[0]?.message?.content || '';
  agent2 = JSON.parse(content);
} catch (e) {
  parseError = String(e.message || e);
}

const draft = String(agent2?.finalMessage || agent2?.rewrittenMessage || prev.agent1?.draftMessage || '');
const findings = [];
const blocked = [
  [/100%\s*money[- ]back/i, 'guarantee_money_back'],
  [/guaranteed\s+(leads|roi|revenue|results)/i, 'guarantee_results'],
  [/unlimited\s+custom/i, 'unlimited_custom'],
  [/buy\.stripe\.com|checkout\.stripe\.com|paddle\.com\/checkout/i, 'fake_processor_link'],
  [/\d{1,2}%\s*off|discount code/i, 'unauthorized_discount'],
  [/\biban\b|send crypto to/i, 'bank_details']
];
for (const [re, code] of blocked) {
  if (re.test(draft)) findings.push({ code, severity: 'block' });
}

const pkgId = prev.agent1?.checkoutPackageId || prev.agent1?.recommendedPackageId;
const pkg = (prev.truth.packages || []).find(p => p.id === pkgId);
if (pkgId && !pkg) findings.push({ code: 'unknown_package_id', severity: 'block' });

if (prev.agent1?.claimedPriceEur != null && pkg?.anchorEur != null) {
  if (Math.abs(Number(prev.agent1.claimedPriceEur) - Number(pkg.anchorEur)) > 1) {
    findings.push({ code: 'price_mismatch', severity: 'block' });
  }
}

let checkoutOk = true;
let checkoutUrl = prev.platformCheckoutUrl || agent2?.approvedCheckoutUrl || null;
if (checkoutUrl) {
  try {
    const u = new URL(checkoutUrl);
    const base = new URL(prev.checkoutBase);
    if (u.origin !== base.origin) { checkoutOk = false; findings.push({ code: 'checkout_wrong_origin', severity: 'block' }); }
    if (/stripe\.com|paddle\.com|lemonsqueezy\.com/.test(u.hostname)) {
      checkoutOk = false; findings.push({ code: 'checkout_processor_host', severity: 'block' });
    }
  } catch {
    checkoutOk = false; findings.push({ code: 'checkout_unparseable', severity: 'block' });
  }
}

const blocks = findings.filter(f => f.severity === 'block').length;
let factuality = Math.max(0, 1 - blocks * 0.25);
if (typeof agent2?.factualityScore === 'number') {
  factuality = Math.min(factuality, agent2.factualityScore);
}

const supervisorRejected = agent2?.status === 'REJECTED' || parseError;
const ok = !supervisorRejected && blocks === 0 && factuality >= 0.85;

let finalMessage = '';
if (ok) {
  finalMessage = draft.trim();
  const footer = prev.truth.terms.disclaimerFooter;
  if (footer && !finalMessage.includes('omnigrouptech.com/legal/terms')) {
    finalMessage += '\n\n' + footer;
  }
  if (checkoutUrl && !finalMessage.includes(checkoutUrl)) {
    finalMessage += '\n\nOfficial checkout: ' + checkoutUrl;
  }
}

const audit = {
  leadId: prev.lead.id,
  title: prev.lead.title,
  score: prev.agent1?.relevanceScore,
  packageId: pkgId || null,
  status: ok ? (agent2?.status === 'REWRITTEN' ? 'REWRITTEN' : 'APPROVED') : 'REJECTED',
  factualityScore: Number(factuality.toFixed(3)),
  findings,
  parseError,
  at: new Date().toISOString()
};

return [{
  json: {
    ...prev,
    agent2,
    guardrail: {
      ok,
      status: audit.status,
      factualityScore: audit.factualityScore,
      findings,
      finalMessage,
      approvedCheckoutUrl: ok ? checkoutUrl : null
    },
    audit
  }
}];

const item = $input.first().json;
const fs = require('fs');
const path = '/home/node/outreach-data/audit-log.jsonl';
const row = {
  stage: item.guardrail?.ok ? 'dispatched_or_queued' : 'rejected',
  outreachEnabled: item.outreachEnabled,
  outreachMode: item.outreachMode,
  audit: item.audit,
  messagePreview: (item.guardrail?.finalMessage || '').slice(0, 280),
  checkout: item.guardrail?.approvedCheckoutUrl || null
};
try {
  fs.appendFileSync(path, JSON.stringify(row) + '\n');
} catch (e) {
  // sandbox may block fs — still return audit in item
  row.fsError = String(e.message || e);
}
return [{ json: { ...item, logged: true, logRow: row } }];

const item = $input.first().json;
return [{ json: {
  stage: 'rejected_or_low_score',
  leadId: item.lead?.id,
  reason: item.guardrail?.findings || item.agent1?.discardReason || 'scout_fail',
  factualityScore: item.guardrail?.factualityScore ?? null,
  at: new Date().toISOString()
}}];

const e = $input.first().json;
const safe = {
  at: new Date().toISOString(),
  workflow: e.workflow?.name,
  executionId: e.execution?.id,
  node: e.node?.name,
  message: String(e.execution?.error?.message || e.error?.message || 'unknown').slice(0, 500)
};
try {
  const fs = require('fs');
  fs.appendFileSync('/home/node/outreach-data/errors.jsonl', JSON.stringify(safe) + '\n');
} catch (_) {}
return [{ json: safe }];
